const main = async (): Promise<void> => {
  if (PAIR.length === 2) {
    const [a, b] = await Promise.all([scan(PAIR[0]), scan(PAIR[1])]);
    show(a); show(b);
    // Paired difference needs the records themselves, not the aggregates.
    const read = async (id: string): Promise<Map<number, GameRecord>> => {
      const m = new Map<number, GameRecord>();
      const rl = createInterface({ input: createReadStream(pathOf(id)), crlfDelay: Infinity });
      for await (const line of rl) {
        if (!line) continue;
        const r = JSON.parse(line) as GameRecord;
        if (m.has(r.gameId)) throw new Error(`duplicate gameId ${r.gameId} in ${pathOf(id)}`);
        m.set(r.gameId, r);
      }
      return m;
    };
    const [A, B] = await Promise.all([read(PAIR[0]), read(PAIR[1])]);
    const ids = [...A.keys()].filter(i => B.has(i));
    const mean = (xs: number[]): number => xs.reduce((x, y) => x + y, 0) / (xs.length || 1);
    const ci = (xs: number[]): number => {
      const n = xs.length; const m = mean(xs); if (n < 2) return NaN;
      const v = xs.reduce((x, y) => x + (y - m) ** 2, 0) / (n - 1);
      return 1.959964 * Math.sqrt(v / n);
    };
    const diff = (f: (r: GameRecord) => number): [number, number] => {
      const xs = ids.map(i => {
        const rA = A.get(i)!;
        const rB = B.get(i)!;
        if (rA.startFen !== rB.startFen) throw new Error(`gameId ${i}: startFen mismatch`);
        if (rA.seed !== rB.seed) throw new Error(`gameId ${i}: seed mismatch`);
        if (rA.openingPlies !== rB.openingPlies) throw new Error(`gameId ${i}: openingPlies mismatch`);
        if (rA.colourSwapped !== rB.colourSwapped) throw new Error(`gameId ${i}: colourSwapped mismatch`);
        return f(rA) - f(rB);
      });
      return [mean(xs), ci(xs)];
    };
    const [res, resCI] = diff(r => r.result);
    const [dec, decCI] = diff(r => (r.result !== 0.5 ? 1 : 0));
    const [ply, plyCI] = diff(r => r.plies);
    console.log(`\npaired ${ids.length} games (${PAIR[0]} minus ${PAIR[1]})`);
    console.log(`  unmatched A: ${A.size - ids.length}, unmatched B: ${B.size - ids.length}`);
    const fmt = (v: number, ciVal: number) => {
      if (isNaN(ciVal)) return v >= 0 ? `+${v.toFixed(3)}` : v.toFixed(3);
      return `${v >= 0 ? '+' : ''}${v.toFixed(3)} ± ${ciVal.toFixed(3)}`;
    };
    const fmtPly = (v: number, ciVal: number) => {
      if (isNaN(ciVal)) return v >= 0 ? `+${v.toFixed(1)}` : v.toFixed(1);
      return `${v >= 0 ? '+' : ''}${v.toFixed(1)} ± ${ciVal.toFixed(1)}`;
    };
    console.log(`  result ${fmt(res, resCI)} · decisive ${fmt(dec, decCI)} · plies ${fmtPly(ply, plyCI)}`);
    return;
  }
  for (const id of RUNS) show(await scan(id));
};

